package com.campusiq.auth.service; import com.campusiq.auth.dto.RegisterRequest; import com.campusiq.auth.security.JwtService; import com.campusiq.user.entity.User; import com.campusiq.user.repository.UserRepository; import org.junit.jupiter.api.Test; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; class AuthServiceTest {@Test void storesPasswordAsBcryptHash(){var repo=mock(UserRepository.class);when(repo.existsByEmail(anyString())).thenReturn(false);when(repo.save(any())).thenAnswer(i->i.getArgument(0));var auth=new AuthService(repo,new BCryptPasswordEncoder(),new JwtService("Q2FtcHVzSVEtdGhpcy1pcy1hLWRldmVsb3BtZW50LWtleS0zMi1ieXRlcy0=",10));assertThatCode(()->auth.register(new RegisterRequest("Ada","ada@example.com","password1"))).doesNotThrowAnyException();var saved=org.mockito.ArgumentCaptor.forClass(User.class);verify(repo).save(saved.capture());assertThat(saved.getValue().getPasswordHash()).isNotEqualTo("password1").startsWith("$2");}}
